function loadState(){try{const saved=JSON.parse(localStorage.getItem(STORE_KEY)||'{}');return {...structuredClone(DEFAULTS),...saved,profile:{...DEFAULTS.profile,...(saved.profile||{})},stats:{...DEFAULTS.stats,...(saved.stats||{})}};}catch{return structuredClone(DEFAULTS);}}
function saveState(){try{localStorage.setItem(STORE_KEY,JSON.stringify(state));}catch{toast('Storage is full. Export a backup and clear old game history.');}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300);}
function addXP(amount,reason){state.xp+=amount;state.gamesPlayed+=1;state.history.unshift({game:currentGame,at:new Date().toISOString(),xp:amount,reason});state.history=state.history.slice(0,80);checkAchievements();saveState();}
function checkAchievements(){const unlock=[];if(state.gamesPlayed>=1)unlock.push('first-game');if(state.gamesPlayed>=5)unlock.push('five-games');if(state.gamesPlayed>=20)unlock.push('game-night');if(state.xp>=100)unlock.push('century');if(state.wins>=5)unlock.push('winner-five');if(state.customDeck.length>=5)unlock.push('deck-maker');unlock.forEach(id=>{if(!state.achievements.includes(id)){state.achievements.push(id);toast('Achievement unlocked! '+ACHIEVEMENTS[id].name);}});}
const ACHIEVEMENTS={'first-game':{name:'First Round',desc:'Play your first game',icon:'🎮'},'five-games':{name:'Warm Up',desc:'Play five games',icon:'🔥'},'game-night':{name:'Game Night Pro',desc:'Play twenty games',icon:'🎉'},century:{name:'Century Club',desc:'Earn 100 XP',icon:'💯'},'winner-five':{name:'Winning Habit',desc:'Win five rounds',icon:'🏆'},'deck-maker':{name:'Deck Creator',desc:'Create five custom prompts',icon:'📝'}};
function rand(arr){return arr[Math.floor(Math.random()*arr.length)];}
function pickUnique(list,key){state.usedPrompts=state.usedPrompts||{};let used=state.usedPrompts[key]||[];let fresh=list.filter(item=>!used.includes(typeof item==='string'?item:JSON.stringify(item)));if(!fresh.length){used=[];fresh=list;}const picked=rand(fresh);const id=typeof picked==='string'?picked:JSON.stringify(picked);state.usedPrompts[key]=[...used,id];saveState();return picked;}
function shuffle(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function norm(s){return String(s||'').toLowerCase().replace(/[^a-z0-9]/g,'').trim();}
function nav(to){closeGame();activeNav=to;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.nav===to));render();window.scrollTo({top:0,behavior:'smooth'});}
function gameCard(g){return `<button class="game-card" data-game="${g[0]}"><span class="game-tag">PLAY NOW</span><div class="game-icon">${g[3]}</div><h3>${esc(g[1])}</h3><p>${esc(g[4])}</p></button>`;}
function section(title,action='',content=''){return `<div class="section-head"><h2>${title}</h2>${action?`<button data-nav="${action}">See all →</button>`:''}</div>${content}`;}
function renderHome(){const level=Math.floor(state.xp/100)+1;const featured=GAMES[12+((new Date().getDate())%12)];return `<section class="hero"><p class="eyebrow">WELCOME TO YOUR GAME NIGHT</p><h1>Hey ${esc(state.profile.name)}.<br>Let the fun begin.</h1><p class="subtext">Couples, friends and chaotic little challenges — all ready on this device, even offline.</p><div class="hero-row"><button class="primary-btn" data-nav="games">Explore games <span>→</span></button><button class="ghost-btn" data-game="${featured[0]}">Today’s pick: ${featured[3]}</button></div><div class="stats-grid"><div class="stat-card"><b>${state.xp}</b><small>Total XP</small></div><div class="stat-card"><b>${state.gamesPlayed}</b><small>Games played</small></div><div class="stat-card"><b>Lv ${level}</b><small>Your level</small></div></div></section>${section('Pick up the fun','games',`<div class="feature-card"><div class="game-icon">${featured[3]}</div><div style="flex:1;min-width:0"><b>${featured[1]}</b><p>${featured[4]}</p></div><button class="primary-btn" data-game="${featured[0]}">Play</button></div>`)}${section('Popular games','games',`<div class="game-grid">${[GAMES[0],GAMES[2],GAMES[4],GAMES[12]].map(gameCard).join('')}</div>`)}${section('Your next little win','rewards',`<div class="panel"><div style="display:flex;justify-content:space-between;gap:10px"><b>Level ${level} progress</b><span class="pill">${state.xp%100}/100 XP</span></div><div class="progress" style="margin:12px 0 7px"><span style="width:${state.xp%100}%"></span></div><small class="muted">Play a round to earn XP and unlock achievements.</small></div>`)}<div class="footer-note">Made for your people. Saved on this device. No account needed.</div>`;}
function renderGames(){const matches=GAMES.filter(g=>(activeCategory==='all'||g[2].toLowerCase()===activeCategory)&&(!searchText||g.join(' ').toLowerCase().includes(searchText)));return `<p class="eyebrow">THE GAME LIBRARY</p><h1>Choose your game.</h1><p class="subtext">24 ways to make a normal evening more fun.</p><div class="search-row"><input id="game-search" class="search-input" placeholder="Search games..." value="${esc(searchText)}"><button class="secondary-btn" data-action="clear-search">Clear</button></div><div class="chip-row">${CATEGORIES.map(c=>`<button class="chip ${activeCategory===c.toLowerCase()?'active':''}" data-category="${c.toLowerCase()}">${c}</button>`).join('')}</div><div class="game-grid" style="margin-top:10px">${matches.map(gameCard).join('')||'<div class="empty-state">No games found. Try another search.</div>'}</div><div class="footer-note">All listed games support local play. Some are designed for passing one phone between players.</div>`;}
function renderParty(){return `<p class="eyebrow">MAKE IT A GAME NIGHT</p><h1>Party mode.</h1><p class="subtext">Pick a quick game, add your people and pass the phone around.</p><div class="panel"><h3>Players this round</h3><label class="field-label">Your name</label><input id="profile-name-inline" class="field-input" value="${esc(state.profile.name)}"><label class="field-label">Partner / player two</label><input id="partner-name-inline" class="field-input" value="${esc(state.profile.partner)}"><label class="field-label">Group names (2–10, comma-separated)</label><input id="group-names-inline" class="field-input" value="${esc(state.profile.groupNames||`${state.profile.name}, ${state.profile.partner}`)}"><div class="game-actions"><button class="primary-btn" data-action="save-names">Save players</button></div><p class="tiny">You can change names any time. No sign-in or room code required.</p></div><div class="game-grid">${[GAMES[0],GAMES[1],GAMES[13],GAMES[14],GAMES[15],GAMES[20]].map(gameCard).join('')}</div><div class="panel"><h3>Game Night Playlist</h3><p class="muted">A ready-made 20-minute mix of conversation, laughs and a quick battle.</p><button class="primary-btn" data-action="playlist">Start playlist →</button></div>`;}
function renderRewards(){const unlocked=state.achievements;return `<p class="eyebrow">YOUR LITTLE WINS</p><h1>Rewards room.</h1><p class="subtext">Every round earns XP. Your progress stays on this device.</p><div class="stats-grid"><div class="stat-card"><b>${state.xp}</b><small>Total XP</small></div><div class="stat-card"><b>${Math.floor(state.xp/100)+1}</b><small>Level</small></div><div class="stat-card"><b>${state.wins}</b><small>Wins</small></div></div><div class="panel"><div style="display:flex;justify-content:space-between"><b>Next level</b><span class="pill">${state.xp%100}/100 XP</span></div><div class="progress" style="margin-top:12px"><span style="width:${state.xp%100}%"></span></div></div>${section('Achievements','',Object.entries(ACHIEVEMENTS).map(([id,a])=>`<div class="achievement ${unlocked.includes(id)?'':'locked'}"><div class="medal">${a.icon}</div><div style="flex:1"><b>${a.name}</b><div class="tiny">${a.desc}</div></div><span class="pill">${unlocked.includes(id)?'UNLOCKED':'LOCKED'}</span></div>`).join(''))}${section('Recent rounds','',state.history.length?state.history.slice(0,8).map(h=>`<div class="list-row"><div><b>${esc(GAME_MAP[h.game]?.[1]||h.game)}</b><small>${new Date(h.at).toLocaleString()}</small></div><span class="pill">+${h.xp} XP</span></div>`).join(''):'<div class="empty-state">No rounds yet. Play your first game to start your history.</div>')}`;}
function renderProfile(){return `<p class="eyebrow">YOUR PLAYER CARD</p><h1>Make it yours.</h1><div class="panel"><div style="display:flex;align-items:center;gap:13px"><div class="brand-mark" style="width:55px;height:55px;border-radius:18px;font-size:26px">${esc(state.profile.avatar)}</div><div><h2 style="margin:0">${esc(state.profile.name)}</h2><div class="muted">Level ${Math.floor(state.xp/100)+1} · ${state.xp} XP</div></div></div><label class="field-label">Your display name</label><input id="profile-name" class="field-input" maxlength="24" value="${esc(state.profile.name)}"><label class="field-label">Partner / player two name</label><input id="profile-partner" class="field-input" maxlength="24" value="${esc(state.profile.partner)}"><label class="field-label">Group names (2–10, comma-separated)</label><input id="profile-group-names" class="field-input" value="${esc(state.profile.groupNames||`${state.profile.name}, ${state.profile.partner}`)}"><label class="field-label">Avatar</label><div class="chip-row">${['💗','🔥','⭐','🎮','🐼','🦊','🐸','🌙','🍒','🦄'].map(e=>`<button class="chip ${state.profile.avatar===e?'active':''}" data-avatar="${e}">${e}</button>`).join('')}</div><div class="game-actions"><button class="primary-btn" data-action="save-profile">Save profile</button></div></div><div class="panel"><h3>Your custom deck studio</h3><p class="muted">${BUILTIN_PROMPT_COUNT} built-in prompts across the game library. Add your own truth, dare or game prompts; they stay private on this device.</p><label class="field-label">Deck type</label><select id="deck-type" class="field-select"><option value="truth">Truth</option><option value="dare">Dare</option><option value="romantic">Romantic</option><option value="flirty">Flirty</option><option value="would-you-rather">Would You Rather (use A | B)</option></select><label class="field-label">Your prompt</label><textarea id="deck-prompt" class="field-area" rows="3" maxlength="240" placeholder="Write a prompt. For Would You Rather use option A | option B."></textarea><button class="primary-btn" style="margin-top:9px" data-action="add-deck">Add to my deck</button><div class="list-row"><div><b>${state.customDeck.length} custom prompts</b><small>Stored locally</small></div><button class="secondary-btn" data-action="view-deck">View deck</button></div></div><div class="panel"><h3>Backup & privacy</h3><p class="muted">Export your profile, scores, history and custom deck as a JSON file. Import it on another device to transfer your local progress.</p><div class="game-actions"><button class="secondary-btn" data-action="export">Export backup</button><button class="secondary-btn" data-action="import">Import backup</button><input id="backup-file" type="file" accept="application/json" hidden></div><div class="switch-row"><span>Sound effects</span><input type="checkbox" id="sound-setting" ${state.profile.sound?'checked':''}></div><div class="switch-row"><span>Haptic feedback</span><input type="checkbox" id="haptic-setting" ${state.profile.haptics?'checked':''}></div><p class="tiny">All personal data stays in your browser storage. Clearing browser data can erase it; keep a backup.</p><button class="danger-btn" data-action="reset-data">Reset local data</button></div><div class="footer-note">YaarJam V2 · Offline-first · No backend · No login · No tracking</div>`;}
function render(){const root=document.getElementById('app');root.innerHTML=activeNav==='home'?renderHome():activeNav==='games'?renderGames():activeNav==='party'?renderParty():activeNav==='rewards'?renderRewards():renderProfile();document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.nav===activeNav));document.getElementById('avatar-initial').textContent=state.profile.avatar;}

function openGame(id){if(!GAME_MAP[id])return;closeGame(false);currentGame=id;gameState={round:1,score:0,skips:0,votes:{},answers:{},revealed:false,used:[],deck:'classic',level:'easy'};const layer=document.getElementById('game-layer');layer.classList.add('open');layer.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';renderGame();}
function closeGame(refresh=true){if(reactionTimer)clearTimeout(reactionTimer);reactionTimer=null;reactionReady=false;if(wordInterval)clearInterval(wordInterval);wordInterval=null;const layer=document.getElementById('game-layer');layer.classList.remove('open');layer.setAttribute('aria-hidden','true');layer.innerHTML='';document.body.style.overflow='';currentGame=null;if(playlistQueue.length){const next=playlistQueue.shift();setTimeout(()=>openGame(next),80);}else if(refresh)render();}
function gameShell(body){const g=GAME_MAP[currentGame];return `<div class="game-wrap"><div class="game-top"><div><p class="eyebrow" style="margin:0 0 4px">YAARJAM ARCADE</p><h2>${g[3]} ${esc(g[1])}</h2></div><button class="close-game" data-action="close-game" aria-label="Close game">✕</button></div><div class="game-body">${body}</div><div class="footer-note">Local play · Pass the phone · Skip anything uncomfortable</div></div>`;}
function promptCard(label,text){return `<div class="question-card"><div class="q-label">${label}</div><div class="q-text">${esc(text)}</div></div>`;}
function actionButton(label,action,cls='primary-btn',disabled=false){return `<button class="${cls}" data-action="${action}" ${disabled?'disabled':''}>${label}</button>`;}
function nameList(){const names=String(state.profile.groupNames||'').split(',').map(v=>v.trim()).filter(Boolean).slice(0,10);if(names.length>=2)return names;return [state.profile.name||'Player 1',state.profile.partner||'Player 2'];}
function completeRound(xp=10,reason='Round completed'){addXP(xp,reason);toast(`+${xp} XP earned!`);}
function showQuestionGame(title,subtitle,text,controls){return `<div class="game-hero"><div class="game-emoji">${GAME_MAP[currentGame][3]}</div><h3>${title}</h3><p>${subtitle}</p></div>${text}${controls}`;}

function renderGame(){if(!currentGame)return;let html='';switch(currentGame){
case 'truth-dare-friends':case 'couple-truth-dare':html=renderTruthDare();break;
case 'tic-tac-toe':html=renderTicTacToe();break;
case 'ludo':html=renderLudo();break;
case 'would-you-rather':case 'this-or-that':html=renderChoiceVote();break;
case 'never-have-i-ever':html=renderNever();break;
case 'most-likely-to':html=renderMostLikely();break;
case 'partner-quiz':html=renderPartnerQuiz();break;
case 'our-story':html=renderOurStory();break;
case 'guess-word':html=renderGuessWord();break;
case 'rock-paper-scissors':html=renderRPS();break;
case 'blind-ranking':html=renderBlindRanking();break;
case 'secret-mission':html=renderSecretMission();break;
case 'emoji-decode':html=renderEmojiDecode();break;
case 'bluff-battle':html=renderBluffBattle();break;
case 'couple-bingo':html=renderBingo();break;
case 'memory-match':html=renderMemory();break;
case 'story-builder':html=renderStoryBuilder();break;
case 'date-night':html=renderDateNight();break;
case 'red-flag':html=renderRedFlag();break;
case 'same-brain':html=renderSameBrain();break;
case 'twenty-questions':html=renderTwentyQuestions();break;
case 'reaction-battle':html=renderReaction();break;
}
document.getElementById('game-layer').innerHTML=gameShell(html);}

function renderTruthDare(){const packs={classic:[TRUTHS,DARES],romantic:[ROMANTIC,ROMANTIC_DARES],flirty:[FLIRTY,FLIRTY_DARES],bold:[BOLD,BOLD_DARES],'after-dark':[AFTER_DARK,AFTER_DARK_DARES]};const pack=gameState.deck||'classic';const isDare=gameState.kind==='dare';const pool=packs[pack]||packs.classic;const custom=state.customDeck.filter(d=>d.type===(isDare?'dare':pack==='classic'?'truth':pack));const base=(isDare?pool[1]:pool[0]);const level=gameState.level||'medium';const levelExtra=isDare?(level==='bold'?BOLD_DARES:level==='extreme'?[...BOLD_DARES,...AFTER_DARK_DARES]:[]):(level==='bold'?[...BOLD,...FLIRTY]:level==='extreme'?[...BOLD,...FLIRTY,...AFTER_DARK]:[]);const cap=level==='chill'?10:level==='easy'?18:base.length;const list=base.slice(0,cap).concat(levelExtra,custom.map(d=>d.text));const item=gameState.prompt||rand(list);gameState.prompt=item;return showQuestionGame('Pick your next move',currentGame==='couple-truth-dare'?'Two players · Choose a pack that feels right.':'Friends mode · Take turns and keep it light.',promptCard(isDare?'DARE':'TRUTH',item),`<div class="panel"><label class="field-label">Prompt pack</label><div class="chip-row">${['classic','romantic','flirty','bold','after-dark'].map(p=>`<button class="chip ${pack===p?'active':''}" data-pack="${p}">${p==='after-dark'?'After Dark 18+':p[0].toUpperCase()+p.slice(1)}</button>`).join('')}</div>${pack==='after-dark'?'<div class="notice warning">18+ pack. Only use with consenting adults. Anyone can skip or change the pack.</div>':''}<label class="field-label">Difficulty</label><div class="chip-row">${['chill','easy','medium','bold','extreme'].map(v=>`<button class="chip ${gameState.level===v?'active':''}" data-level="${v}">${v}</button>`).join('')}</div></div><div class="two-col"><button class="secondary-btn" data-kind="truth">🗝 Truth</button><button class="secondary-btn" data-kind="dare">⚡ Dare</button></div><div class="game-actions">${actionButton('Next prompt →','next-td')}${actionButton('Skip this one','skip-td','ghost-btn')}</div><p class="tiny">Round ${gameState.round} · Completed ${gameState.score} · Skipped ${gameState.skips}</p>`);}
function renderTicTacToe(){if(!gameState.board)gameState.board=Array(9).fill('');if(!gameState.turn)gameState.turn='X';if(!gameState.mode)gameState.mode='computer';const best=gameState.bestOf||3,target=Math.ceil(best/2),you=gameState.matchWins||0,opponent=gameState.oppWins||0,matchOver=you>=target||opponent>=target,winner=checkTTT(gameState.board),full=gameState.board.every(Boolean),done=Boolean(winner||full||matchOver);let status=matchOver?(you>opponent?'You win the series!':opponent>you?'Opponent wins the series!':'Series complete!'):winner?`${winner==='X'?nameList()[0]:gameState.mode==='computer'?'Computer':nameList()[1]} wins this round!`:full?'It is a draw.':`${gameState.turn==='X'?nameList()[0]:gameState.mode==='computer'?'Computer':nameList()[1]}'s turn`;return showQuestionGame('Quick match, big rivalry',`Best of ${best} · You ${you} — Opponent ${opponent}`,`<div class="panel" style="text-align:center"><div class="badge-row" style="justify-content:center"><button class="chip ${gameState.mode==='computer'?'active':''}" data-ttt-mode="computer">Vs computer</button><button class="chip ${gameState.mode==='friend'?'active':''}" data-ttt-mode="friend">Two players</button></div>${gameState.mode==='computer'?`<label class="field-label">Computer skill</label><div class="chip-row" style="justify-content:center">${['easy','medium','hard'].map(v=>`<button class="chip ${(gameState.aiLevel||'medium')===v?'active':''}" data-ai="${v}">${v}</button>`).join('')}</div>`:''}<label class="field-label">Series</label><div class="chip-row" style="justify-content:center">${[3,5,7].map(n=>`<button class="chip" data-best="${n}">${n===best?'✓ ':''}Best of ${n}</button>`).join('')}</div><div class="board">${gameState.board.map((v,i)=>`<button data-cell="${i}" ${v||done?'disabled':''}>${v==='X'?'×':v==='O'?'○':''}</button>`).join('')}</div><h3>${status}</h3><p class="tiny">${done?'Round complete. Continue the series or start a new one.':'Tap an empty square to play.'}</p></div>`,`<div class="game-actions">${actionButton(matchOver?'New series':'Next round',matchOver?'new-ttt':'reset-ttt','secondary-btn')}${actionButton('Reset series','new-ttt','ghost-btn')}</div>`);}
function checkTTT(b){for(const [a,c,d] of [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]])if(b[a]&&b[a]===b[c]&&b[a]===b[d])return b[a];return null;}
function botMove(board,level='medium'){const empty=board.map((v,i)=>v?'':i).filter(v=>v!=='');if(level==='easy')return rand(empty);if(level==='hard'){const minimax=(b,turn)=>{const win=checkTTT(b);if(win==='O')return 10;if(win==='X')return -10;if(b.every(Boolean))return 0;const scores=[];for(const i of emptyCells(b)){b[i]=turn;const score=minimax(b,turn==='O'?'X':'O');b[i]='';scores.push({i,score});}return turn==='O'?Math.max(...scores.map(x=>x.score)):Math.min(...scores.map(x=>x.score));};let best=null,score=-Infinity;for(const i of empty){board[i]='O';const v=minimax(board,'X');board[i]='';if(v>score){score=v;best=i;}}return best;}const test=(b,p)=>{for(let i=0;i<9;i++)if(!b[i]){b[i]=p;if(checkTTT(b)===p){b[i]='';return i;}b[i]='';}return -1;};let i=test(board,'O');if(i>=0)return i;i=test(board,'X');if(i>=0)return i;if(!board[4])return 4;const corners=[0,2,6,8].filter(x=>!board[x]);return corners.length?rand(corners):[1,3,5,7].find(x=>!board[x]);}
function emptyCells(b){return b.map((v,i)=>v?'':i).filter(v=>v!=='');}
function renderLudoBoard(s){const path=[];for(let c=0;c<14;c++)path.push([0,c]);for(let r=1;r<14;r++)path.push([r,13]);for(let c=12;c>=0;c--)path.push([13,c]);for(let r=12;r>=1;r--)path.push([r,0]);const occupied={};const offsets=[0,13,26,39];s.players.forEach((p,pi)=>p.tokens.forEach((progress,ti)=>{if(progress<0||progress>51)return;const pos=(offsets[pi]+progress)%52;const [r,c]=path[pos];const key=r+','+c;(occupied[key]||= []).push({pi,ti});}));const cells=[];for(let r=0;r<14;r++)for(let c=0;c<14;c++){const key=r+','+c;const pi=path.findIndex(x=>x[0]===r&&x[1]===c);const tokens=occupied[key]||[];const isHome=(r>=5&&r<=8&&c>=5&&c<=8);const base=r<6&&c<6?'base-red':r<6&&c>7?'base-purple':r>7&&c<6?'base-green':r>7&&c>7?'base-yellow':'';cells.push(`<div class="ludo-cell ${pi>=0?'track':''} ${isHome?'home-center':''} ${base}">${pi>=0?tokens.map(t=>`<span class="ludo-dot dot-${t.pi}" title="${esc(s.players[t.pi].name)} token ${t.ti+1}">${t.ti+1}</span>`).join('')||'·':isHome?'✦':''}</div>`);}return `<div class="ludo-board">${cells.join('')}</div>`;}
function renderLudo(){if(!gameState.ludo)gameState.ludo={players:[{name:nameList()[0],color:'❤️',bot:false,tokens:[-1,-1,-1,-1]},{name:'Computer',color:'💜',bot:true,tokens:[-1,-1,-1,-1]}],turn:0,dice:null,rolled:false,legal:[],winner:null};const s=gameState.ludo;const p=s.players[s.turn];return showQuestionGame('Race all four tokens home','Local Ludo · Roll a six to bring a token out. Capture on unsafe squares.',`<div class="panel"><div class="badge-row"><button class="chip ${s.players.length===2&&s.players[1].bot?'active':''}" data-ludo-mode="bot">Vs computer</button><button class="chip ${s.players.length===2&&!s.players[1].bot?'active':''}" data-ludo-mode="duo">2 players</button><button class="chip ${s.players.length===3?'active':''}" data-ludo-mode="trio">3 players</button><button class="chip ${s.players.length===4?'active':''}" data-ludo-mode="quad">4 players</button></div>${renderLudoBoard(s)}${s.players.map((pl,i)=>`<div class="list-row"><div><b>${pl.color} ${esc(pl.name)}</b><small>${pl.tokens.filter(x=>x===58).length}/4 home · ${pl.tokens.filter(x=>x>=0&&x<58).length} on track</small></div><span class="pill">${s.turn===i?'TURN':''}</span></div>`).join('')}<div class="big-timer" style="font-size:38px">${s.dice??'🎲'}</div><p style="text-align:center">${s.winner?`${esc(s.winner)} wins!`:`${esc(p.name)}’s turn`}</p><div class="token-row" style="justify-content:center">${p.tokens.map((v,i)=>`<button class="token ${s.legal.includes(i)?'good':''}" data-ludo-token="${i}" ${!s.rolled||!s.legal.includes(i)||s.winner?'disabled':''}>Token ${i+1}<br><small>${v===-1?'Yard':v===58?'Home':`Step ${v}`}</small></button>`).join('')}</div><p class="tiny" style="text-align:center">${s.rolled?'Choose a highlighted token.':s.winner?'Match complete.':'Roll the die to begin your turn.'}</p></div>`,`<div class="game-actions">${actionButton('🎲 Roll dice','ludo-roll', 'primary-btn',s.rolled||!!s.winner||p.bot)}${actionButton('Restart match','ludo-reset','ghost-btn')}</div><p class="tiny">A six gives another turn. Capturing an opponent also earns a bonus turn. Exact roll needed to reach home.</p>`);}
function legalLudo(s,die){const p=s.players[s.turn];return p.tokens.map((v,i)=>v===58?-1:v===-1?(die===6?i:-1):(v+die<=58?i:-1)).filter(i=>i>=0);}
function startLudoMode(mode){const n=mode==='trio'?3:mode==='quad'?4:2;const players=Array.from({length:n},(_,i)=>({name:i===0?nameList()[0]:mode==='bot'&&i===1?'Computer':nameList()[i]||`Player ${i+1}`,color:['❤️','💜','💚','💛'][i],bot:mode==='bot'&&i===1,tokens:[-1,-1,-1,-1]}));gameState.ludo={players,turn:0,dice:null,rolled:false,legal:[],winner:null};renderGame();}
function autoLudoBot(){const s=gameState.ludo;if(!s||s.winner||!s.players[s.turn]?.bot)return;setTimeout(()=>{if(!currentGame||currentGame!=='ludo'||!gameState.ludo?.players[gameState.ludo.turn]?.bot)return;const die=1+Math.floor(Math.random()*6);s.dice=die;s.legal=legalLudo(s,die);if(!s.legal.length){if(die!==6)s.turn=(s.turn+1)%s.players.length;s.dice=null;s.rolled=false;s.legal=[];renderGame();if(s.players[s.turn]?.bot)autoLudoBot();return;}s.rolled=true;const idx=rand(s.legal);applyLudoMove(s,idx);if(s.winner){if(s.winner===nameList()[0])state.wins++;completeRound(s.winner===nameList()[0]?30:10,'Ludo computer match');}renderGame();if(!s.winner&&s.players[s.turn]?.bot)autoLudoBot();},550);}
function applyLudoMove(s,idx){const p=s.players[s.turn],old=p.tokens[idx],next=old===-1?0:old+s.dice;p.tokens[idx]=next;let captured=false;const offsets=[0,13,26,39],track=(offsets[s.turn]+next)%52;if(next<52&&![0,8,13,21,26,34,39,47].includes(track)){s.players.forEach((op,playerIndex)=>{if(playerIndex===s.turn)return;op.tokens=op.tokens.map(v=>{if(v>=0&&v<52&&(offsets[playerIndex]+v)%52===track){captured=true;return -1;}return v;});});}if(p.tokens.every(v=>v===58)){s.winner=p.name;s.rolled=false;return;}const bonus=s.dice===6||captured;s.dice=null;s.rolled=false;s.legal=[];if(!bonus)s.turn=(s.turn+1)%s.players.length;}
function renderChoiceVote(){const wyr=currentGame==='would-you-rather';const customWyr=state.customDeck.filter(d=>d.type==='would-you-rather').map(d=>d.text.split('|').map(x=>x.trim()));if(!gameState.choice)gameState.choice=pickUnique(wyr?WYR.concat(customWyr.filter(x=>x.length===2)):THIS_THAT,'choice-'+currentGame);const pair=gameState.choice;const players=[...nameList(),...(gameState.extraPlayers||[])];const turn=Object.keys(gameState.votes||{}).length;if(turn>=players.length)gameState.allVoted=true;return showQuestionGame(wyr?'Two impossible choices':'Pick your favourite',`Round ${gameState.round} · ${players.length} players · Pass the phone after each vote`,promptCard(wyr?'WOULD YOU RATHER?':'THIS OR THAT',wyr?'Choose one option, no neutral answers allowed.':'Which one matches your vibe today?'),`<div class="choice-stack">${pair.map((v,i)=>`<button class="choice-btn" data-vote="${i}" ${turn>=players.length||gameState.revealed?'disabled':''}><b>${i===0?'A':'B'}.</b> ${esc(v)}</button>`).join('')}</div><div class="panel"><div class="list-row"><b>${turn<players.length?esc(players[turn])+' is choosing':'Votes complete'}</b><span class="pill">${Object.keys(gameState.votes||{}).length}/${players.length}</span></div>${gameState.revealed?`<p class="tiny">A: ${Object.values(gameState.votes||{}).filter(x=>x===0).length} votes · B: ${Object.values(gameState.votes||{}).filter(x=>x===1).length} votes</p>`:'<p class="tiny">Vote privately, then reveal the group result.</p>'}</div>${gameState.revealed?`<div class="notice">${Object.values(gameState.votes).filter(x=>x===0).length===Object.values(gameState.votes).filter(x=>x===1).length?'It’s a tie!':Object.values(gameState.votes).filter(x=>x===0).length>Object.values(gameState.votes).filter(x=>x===1).length?'Option A wins the room!':'Option B wins the room!'}</div>`:''}<div class="game-actions">${actionButton(gameState.revealed?'Next question →':'Reveal group votes','next-choice',gameState.revealed?'primary-btn':'secondary-btn',!gameState.revealed&&Object.keys(gameState.votes||{}).length===0)}</div>`);}
function renderNever(){const players=[...nameList(),...(gameState.extraPlayers||[])];if(!gameState.prompt)gameState.prompt=pickUnique(NEVER,'never');const turn=Object.keys(gameState.answers||{}).length;if(turn>=players.length)gameState.revealed=true;return showQuestionGame('Never have I ever…',`Round ${gameState.round} · ${players.length} players · No explanation required`,promptCard('TAKE A TURN',gameState.prompt),`<div class="panel"><h3>${turn<players.length?esc(players[turn])+' — your turn':'Round complete'}</h3><div class="two-col"><button class="choice-btn" data-never="1" ${gameState.revealed?'disabled':''}>🙋 I have</button><button class="choice-btn" data-never="0" ${gameState.revealed?'disabled':''}>🙅 I have not</button></div><p class="tiny">Answers recorded: ${Object.keys(gameState.answers||{}).length}/${players.length}</p>${gameState.revealed?`<div class="notice">${players.map(p=>`${esc(p)}: ${gameState.answers[p]?'I have':'I have not'}`).join('<br>')}</div>`:''}</div><div class="game-actions">${actionButton(gameState.revealed?'Next statement →':'Reveal answers','next-never','primary-btn',!gameState.revealed&&Object.keys(gameState.answers||{}).length===0)}</div>`);}
function renderMostLikely(){const players=[...nameList(),...(gameState.extraPlayers||[])];if(!gameState.prompt)gameState.prompt=pickUnique(MOST,'most');const turn=Object.keys(gameState.answers||{}).length;if(turn>=players.length)gameState.revealed=true;return showQuestionGame('Point to someone!',`Round ${gameState.round} · Everyone gets one vote`,promptCard('MOST LIKELY TO…',gameState.prompt),`<div class="panel"><p class="tiny">${gameState.revealed?'Final votes':'Voter: '+esc(players[turn]||'All votes done')}</p><div class="choice-stack">${players.map(p=>`<button class="choice-btn" data-person="${esc(p)}" ${gameState.revealed?'disabled':''}>${esc(p)} <span class="pill" style="float:right">${gameState.revealed?(gameState.votes[p]||0)+' votes':'Vote'}</span></button>`).join('')}</div>${gameState.revealed?`<div class="notice">Winner: ${esc(players.slice().sort((a,b)=>(gameState.votes[b]||0)-(gameState.votes[a]||0))[0])}</div>`:''}</div><div class="game-actions">${actionButton(gameState.revealed?'Next prompt →':'Reveal votes','next-most','primary-btn',!gameState.revealed&&Object.keys(gameState.answers||{}).length===0)}</div>`);}
function renderPartnerQuiz(){if(!gameState.question)gameState.question=pickUnique(PARTNER_QUESTIONS,'partner');const n=nameList();const step=gameState.step||0;return showQuestionGame('How well do you know me?',`Question ${gameState.round} · Score ${gameState.score||0}`,promptCard('PARTNER QUIZ',gameState.question),`<div class="panel"><b>${step===0?esc(n[0])+' — set the real answer':step===1?esc(n[1])+' — guess the answer': 'Answer reveal'}</b>${step===0?`<input id="quiz-real" class="field-input" placeholder="Type the answer only you know" maxlength="100">${actionButton('Lock answer →','quiz-lock','primary-btn')}`:step===1?`<input id="quiz-guess" class="field-input" placeholder="What do you think?" maxlength="100">${actionButton('Reveal both answers','quiz-reveal','primary-btn')}`:`<div class="notice">${esc(n[0])}: ${esc(gameState.real||'—')}<br>${esc(n[1])}: ${esc(gameState.guess||'—')}</div><p>${gameState.match?'You matched! +15 XP':'Different answers — tell the story behind them.'}</p>${actionButton('Next question →','quiz-next','primary-btn')}`}</div>`);}
function renderOurStory(){if(!gameState.question)gameState.question=pickUnique(STORY_QUESTIONS,'our-story');return showQuestionGame('A little trip down memory lane',`Memory prompt ${gameState.round}`,promptCard('OUR STORY',gameState.question),`<div class="panel"><label class="field-label">Add a memory or detail</label><textarea id="story-note" class="field-area" rows="3" maxlength="300" placeholder="Write a few lines together..."></textarea><div class="game-actions">${actionButton('Save memory +10 XP','story-save')}${actionButton('Next memory prompt','story-next','ghost-btn')}</div>${gameState.memory?`<div class="notice">Saved locally: ${esc(gameState.memory)}</div>`:''}</div>`);}
function renderGuessWord(){if(!gameState.word)gameState.word=pickUnique(WORDS,'guess-word');const sec=gameState.seconds??30;return showQuestionGame('Describe it. Don’t say it.',`Round ${gameState.round} · ${gameState.score||0} points`,promptCard(gameState.revealed?'YOUR WORD':'PASS THE PHONE',gameState.revealed?gameState.word:'Hand the phone to the performer, then reveal the word.'),`<div class="panel"><div class="big-timer" id="word-timer">${sec}s</div>${gameState.revealed?`<p class="tiny">Get your team to guess without saying the word or its obvious variations.</p><div class="game-actions">${actionButton('✓ Guessed it +10','word-point')}${actionButton('Skip word','word-skip','ghost-btn')}</div>`:actionButton('Reveal word & start timer','word-start','primary-btn')}${actionButton('Next word','word-next','secondary-btn')}</div>`);}
function renderRPS(){const score=gameState.rpsScore||[0,0];const over=score[0]>=3||score[1]>=3;return showQuestionGame('Rock, paper, scissors!',`Best of 5 · You ${score[0]} — ${score[1]} Computer`,promptCard(over?'MATCH COMPLETE':'CHOOSE YOUR MOVE',over?(score[0]>score[1]?'You win the match!':'Computer wins the match!'):gameState.rpsChoice?`You picked ${gameState.rpsChoice}. Computer picked ${gameState.rpsBot}. ${gameState.rpsResult}`:'Ready?'),`<div class="two-col">${['Rock','Paper','Scissors'].map((v,i)=>`<button class="choice-btn" data-rps="${v}" ${over?'disabled':''}>${['✊','✋','✌️'][i]} ${v}</button>`).join('')}</div><div class="game-actions">${actionButton('New match','rps-reset','ghost-btn')}</div>`);}
function renderBlindRanking(){const items=gameState.items||shuffle(RANK_ITEMS).slice(0,5);gameState.items=items;const placed=gameState.placed||Array(5).fill(null);const idx=gameState.idx||0;const done=idx>=5;return showQuestionGame('Rank it before the next surprise',`Blind ranking · ${Math.min(idx+1,5)} of 5`,done?promptCard('YOUR FINAL RANKING','All choices revealed. How did you do?'):`<div class="question-card"><div class="q-label">SURPRISE ITEM ${idx+1}</div><div class="q-text">${esc(items[idx])}</div><p class="tiny">Choose an empty position. You cannot move it later.</p></div>`,`<div class="ranking-slots">${placed.map((v,i)=>`<div class="${v?'filled':''}"><b>${i+1}</b><br>${v?esc(v):'Empty'}</div>`).join('')}</div>${done?`<div class="notice">Your ranking is locked. Share your most controversial placement!</div>${actionButton('Play again','rank-reset')}`:`<div class="choice-stack">${placed.map((v,i)=>!v?`<button class="choice-btn" data-rank="${i}">Place at #${i+1}</button>`:'').join('')}</div>`}`);}
function renderSecretMission(){if(!gameState.mission)gameState.mission=pickUnique(MISSIONS,'missions');return showQuestionGame('Can you complete it unnoticed?',`Secret mission · ${gameState.missionNo||1}`,gameState.revealed?promptCard('YOUR SECRET MISSION',gameState.mission):`<div class="question-card"><div class="q-label">HIDDEN CHALLENGE</div><div class="q-text">🔒 Pass the phone to the player.</div><p class="tiny">Only the assigned player should reveal their mission.</p></div>`,`<div class="panel">${actionButton(gameState.revealed?'Hide mission':'Reveal my mission','mission-reveal','secondary-btn')}${gameState.revealed?`<div class="notice">Complete it naturally. Don’t pressure anyone or use private information.</div>${actionButton('Mission complete +20 XP','mission-done')}${actionButton('Give me another mission','mission-next','ghost-btn')}`:''}</div>`);}
function renderEmojiDecode(){if(!gameState.emoji)gameState.emoji=pickUnique(EMOJI_QUIZ,'emoji');return showQuestionGame('What do these emojis mean?',`Puzzle ${gameState.round} · ${gameState.score||0} points`,promptCard('DECODE THE CLUE',gameState.emoji[0]),`<div class="panel"><input id="emoji-answer" class="field-input" placeholder="Your guess..." maxlength="80">${gameState.revealed?`<div class="notice">Answer: ${esc(gameState.emoji[1])}</div>`:''}<div class="game-actions">${actionButton('Check my guess','emoji-check')}${actionButton(gameState.revealed?'Next puzzle':'Reveal answer','emoji-next','ghost-btn')}</div></div>`);}
function renderBluffBattle(){if(!gameState.bluff)gameState.bluff=pickUnique(BLUFFS,'bluff');const b=gameState.bluff;return showQuestionGame('Can you spot the truth?',`Question ${gameState.round} · Pick one answer`,promptCard('BLUFF BATTLE',b[0]),`<div class="choice-stack">${b.slice(1,5).map((v,i)=>`<button class="choice-btn" data-bluff="${i}" ${gameState.revealed?'disabled':''}>${String.fromCharCode(65+i)}. ${esc(v)}</button>`).join('')}</div>${gameState.revealed?`<div class="notice">Correct answer: ${esc(b[1])}. ${gameState.correct?'Nice read! +15 XP':'Good bluff — now you know!'}</div>`:''}<div class="game-actions">${actionButton(gameState.revealed?'Next question':'Reveal answer','bluff-next','primary-btn',!gameState.revealed&&gameState.pick===undefined)}</div>`);}
function renderBingo(){if(!gameState.bingo)gameState.bingo=shuffle(BINGO_TASKS).slice(0,9);const done=gameState.done||[];const lines=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];const wins=lines.some(l=>l.every(i=>done.includes(i)));return showQuestionGame('Tick off your little moments',`Couple Bingo · ${done.length}/9 completed`,promptCard('YOUR BINGO CARD',wins?'BINGO! You completed a line.':'Complete any horizontal, vertical or diagonal line.'),`<div class="bingo-grid">${gameState.bingo.map((v,i)=>`<button class="${done.includes(i)?'done':''}" data-bingo="${i}">${done.includes(i)?'✓ ':''}${esc(v)}</button>`).join('')}</div>${wins?'<div class="notice">Bingo! +25 XP. Make another card?</div>':''}<div class="game-actions">${actionButton('New bingo card','bingo-reset','primary-btn')}${actionButton('Clear marks','bingo-clear','ghost-btn')}</div>`);}
function renderMemory(){if(!gameState.cards){const deck=shuffle(['🍒','🌙','🎮','🐼','⭐','🍕','🦋','🎧']).flatMap((v,i)=>[v,v]);gameState.cards=shuffle(deck);memoryOpened=[];memoryMatched=[];}const opened=memoryOpened,matched=memoryMatched;return showQuestionGame('Find all the matching pairs',`Moves ${gameState.moves||0} · Pairs ${matched.length/2}/8`,promptCard('MEMORY MATCH','Tap two cards to reveal a pair.'),`<div class="memory-grid">${gameState.cards.map((v,i)=>`<button class="${opened.includes(i)||matched.includes(i)?'open':''}" data-memory="${i}" ${matched.includes(i)?'disabled':''}>${opened.includes(i)||matched.includes(i)?v:'?'}</button>`).join('')}</div>${matched.length===16?'<div class="notice">All pairs matched! Great memory.</div>':''}<div class="game-actions">${actionButton('Restart board','memory-reset','secondary-btn')}${actionButton('Finish & earn XP','memory-finish','ghost-btn',matched.length!==16)}</div>`);}
function renderStoryBuilder(){const n=nameList();const lines=gameState.lines||[];const turn=lines.length%2;return showQuestionGame('One story. Two imaginations.',`Line ${lines.length+1} · ${esc(n[turn])} writes next`,promptCard('STORY STARTER',gameState.seed||'It was a perfectly ordinary evening until…'),`<div class="panel"><div class="notice">${lines.map((v,i)=>`<b>${esc(n[i%2])}:</b> ${esc(v)}`).join('<br>')||'Your story starts here.'}</div><label class="field-label">Add the next line</label><textarea id="story-line" class="field-area" rows="2" maxlength="160" placeholder="Continue the story..."></textarea><div class="game-actions">${actionButton('Add line','story-line-add')}${actionButton('Finish story','story-finish','ghost-btn',lines.length<4)}</div>${gameState.finished?`<div class="notice">The story is complete! Copy it or start a new one.</div>${actionButton('Copy story','story-copy','secondary-btn')}${actionButton('New story','story-new','ghost-btn')}`:''}</div>`);}
function renderDateNight(){const vibe=gameState.vibe||'cosy';const budget=gameState.budget||'low';const place=gameState.place||'either';const idea=gameState.idea;return showQuestionGame('Your next date, sorted.',`Choose a vibe, budget and setting.`,promptCard('DATE NIGHT IDEA',idea||'Your surprise plan will appear here.'),`<div class="panel"><label class="field-label">Mood</label><div class="chip-row">${['cosy','adventure','romantic','playful'].map(v=>`<button class="chip ${vibe===v?'active':''}" data-vibe="${v}">${v}</button>`).join('')}</div><label class="field-label">Budget</label><div class="chip-row">${[['low','Under ₹500'],['mid','₹500–1500'],['high','₹1500+']].map(([v,l])=>`<button class="chip ${budget===v?'active':''}" data-budget="${v}">${l}</button>`).join('')}</div><label class="field-label">Setting</label><div class="chip-row">${[['indoor','Indoor'],['outdoor','Outdoor'],['either','Surprise me']].map(([v,l])=>`<button class="chip ${place===v?'active':''}" data-place="${v}">${l}</button>`).join('')}</div>${actionButton('Generate date plan ✨','date-generate','primary-btn')}${idea?`<div class="notice">Add a playlist, snack and one little surprise to make it yours.</div>${actionButton('Share this idea','share-result','secondary-btn')}`:''}</div>`);}
function renderRedFlag(){if(!gameState.flag)gameState.flag=pickUnique(RED_FLAGS,'redflag');const [scenario,...opts]=gameState.flag,players=nameList(),votes=gameState.flagVotes||{},count=Object.keys(votes).length,finished=count>=2;return showQuestionGame('Green, red or somewhere in between?',`Scenario ${gameState.round} · Compare both perspectives`,promptCard('THE SCENARIO',scenario),`<div class="panel"><p class="tiny">${finished?'Both answers revealed':esc(players[count]||players[0])+' — make your choice privately'}</p><div class="choice-stack">${opts.map(v=>`<button class="choice-btn" data-flag="${v}" ${finished?'disabled':''}>${v}</button>`).join('')}</div>${finished?`<div class="notice">${esc(players[0])}: ${esc(votes[players[0]])}<br>${esc(players[1])}: ${esc(votes[players[1]])}<br><b>${votes[players[0]]===votes[players[1]]?'You see this one the same way.':'Different takes — talk about the context.'}</b></div>`:''}</div><div class="game-actions">${actionButton(finished?'Next scenario →':'Votes: '+count+'/2','flag-next','primary-btn',!finished)}</div>`);}
function renderSameBrain(){if(!gameState.same)gameState.same=pickUnique(SAME_BRAIN,'samebrain');const [q,...opts]=gameState.same;const step=gameState.step||0;return showQuestionGame('Can you think alike?',`Question ${gameState.round} · Keep the first answer secret`,promptCard('SAME BRAIN?',q),`<div class="panel"><b>${step===0?esc(nameList()[0])+' chooses':step===1?esc(nameList()[1])+' chooses':'Reveal time'}</b><div class="choice-stack">${opts.map(v=>`<button class="choice-btn" data-same="${v}" ${step===2?'disabled':''}>${esc(v)}</button>`).join('')}</div>${step===2?`<div class="notice">${esc(nameList()[0])}: ${esc(gameState.sameAnswers[0])}<br>${esc(nameList()[1])}: ${esc(gameState.sameAnswers[1])}<br><b>${gameState.sameAnswers[0]===gameState.sameAnswers[1]?'Same brain! +15 XP':'Different minds, still a good match.'}</b></div>${actionButton('Next question','same-next')}`:''}</div>`);}
function renderTwentyQuestions(){if(!gameState.object)gameState.object=pickUnique(OBJECTS,'twenty');const o=gameState.object;if(!gameState.started&&!gameState.hostRevealed)return showQuestionGame('One person sets the mystery',`Mystery ${gameState.round} · Pass the phone to the host`,promptCard('WORD SETTER','Let one player reveal the secret item, then hide the phone and pass it to the guesser.'),`<div class="panel">${actionButton('Reveal secret item to host','twenty-host-reveal','primary-btn')}</div>`);if(gameState.hostRevealed)return showQuestionGame('Secret item — host only',`Category: ${o[1]}`,promptCard('DO NOT SHOW THE GUESSER',o[0]),`<div class="panel"><p class="tiny">Remember this item. Hide the screen and pass the phone to the guesser.</p>${actionButton('Hide & start questions','twenty-hide','primary-btn')}</div>`);return showQuestionGame('Ask. Listen. Make a smart guess.',`Mystery ${gameState.round} · ${gameState.qCount||0}/20 questions used`,promptCard('MYSTERY CATEGORY',`${o[1]} · ${o[2]}`),`<div class="panel"><div class="list-row"><b>Host answer</b><span class="pill">${gameState.lastAnswer||'Waiting'}</span></div><div class="two-col">${actionButton('Yes','twenty-answer-yes','secondary-btn',gameState.revealed||(gameState.qCount||0)>=20)}${actionButton('No','twenty-answer-no','secondary-btn',gameState.revealed||(gameState.qCount||0)>=20)}</div>${gameState.hints?gameState.hints.map((h,i)=>`<div class="list-row"><div><b>Hint ${i+1}</b><small>${esc(h)}</small></div></div>`).join(''):''}<label class="field-label">Make a guess</label><input id="twenty-guess" class="field-input" placeholder="What is the mystery item?"><div class="game-actions">${actionButton('Check guess','twenty-guess','primary-btn')}${actionButton('Ask for a hint','twenty-hint','ghost-btn',gameState.revealed||(gameState.hints||[]).length>=3)}</div>${gameState.revealed?`<div class="notice">Correct! The mystery was ${esc(o[0])}.</div>`:''}<div class="game-actions">${actionButton('New mystery','twenty-new','ghost-btn')}</div></div>`);}
function renderReaction(){const phase=gameState.phase||'idle',times=gameState.reactionTimes||[],players=nameList();let msg=phase==='idle'?'Tap start, then wait for the screen to turn green.':phase==='waiting'?'Wait… do not tap yet!':phase==='ready'?'TAP NOW!':phase==='false'?'Too early! False start.':'Your reaction time';const finished=phase==='done'&&times.length>=2;return showQuestionGame('Ready, set, react!',`Reaction Battle · ${esc(gameState.reactor||players[times.length]||players[0])}`,`<div class="question-card" style="${phase==='ready'?'background:rgba(131,224,194,.2);border-color:var(--mint)':''}"><div class="q-text">${msg}</div>${phase==='done'?`<div class="big-timer">${gameState.time} ms</div>`:''}${finished?`<div class="notice">${esc(players[0])}: ${times[0]} ms<br>${esc(players[1])}: ${times[1]} ms<br><b>${times[0]===times[1]?'It’s a tie!':esc(players[times[0]<times[1]?0:1])+' wins the reaction battle!'}</b></div>`:''}</div>`,`<div class="panel">${phase==='idle'||phase==='false'?actionButton(phase==='false'?'Try again':'Start reaction test','reaction-start','primary-btn'):phase==='done'&&times.length<2?actionButton('Pass phone to '+esc(players[1])+' →','reaction-next-player','primary-btn'):phase==='done'?actionButton('New battle','reaction-reset','primary-btn'):actionButton('TAP!','reaction-tap','primary-btn')}<p class="tiny">Both players take a turn. Wait for the green signal. Tapping early counts as a false start.</p></div>`);}

// Event handling is delegated so every mini-game can re-render without losing its outer listeners.
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.nav){nav(b.dataset.nav);return;}
 if(b.dataset.game){openGame(b.dataset.game);return;}
 if(b.dataset.category){activeCategory=b.dataset.category;render();return;}
 if(b.dataset.ludoMode){startLudoMode(b.dataset.ludoMode);return;}
 if(b.dataset.pack){if(b.dataset.pack==='after-dark'&&!state.profile.ageConfirmed){if(!window.confirm('This pack is intended for consenting adults aged 18+. Continue?'))return;state.profile.ageConfirmed=true;saveState();}gameState.deck=b.dataset.pack;gameState.prompt=null;gameState.kind='truth';renderGame();return;}
 if(b.dataset.level){gameState.level=b.dataset.level;gameState.prompt=null;renderGame();return;}
 if(b.dataset.kind){gameState.kind=b.dataset.kind;gameState.prompt=null;renderGame();return;}
 if(b.dataset.tttMode){gameState.mode=b.dataset.tttMode;renderGame();return;}
 if(b.dataset.ai){gameState.aiLevel=b.dataset.ai;renderGame();return;}
 if(b.dataset.best){gameState.bestOf=Number(b.dataset.best);renderGame();return;}
 if(b.dataset.cell!==undefined){playTTT(Number(b.dataset.cell));return;}
 if(b.dataset.ludoToken!==undefined){const s=gameState.ludo;applyLudoMove(s,Number(b.dataset.ludoToken));if(s.winner){if(s.winner===nameList()[0])state.wins++;completeRound(s.winner===nameList()[0]?30:10,'Ludo match completed');}renderGame();if(!s.winner&&s.players[s.turn].bot)autoLudoBot();return;}
 if(b.dataset.vote!==undefined){if(!gameState.votes)gameState.votes={};const players=[...nameList(),...(gameState.extraPlayers||[])];const who=players[Object.keys(gameState.votes).length];if(who){gameState.votes[who]=Number(b.dataset.vote);renderGame();}return;}
 if(b.dataset.never!==undefined){const players=[...nameList(),...(gameState.extraPlayers||[])];gameState.answers=gameState.answers||{};gameState.answers[players[Object.keys(gameState.answers).length]]=Number(b.dataset.never)===1;renderGame();return;}
 if(b.dataset.person){gameState.votes=gameState.votes||{};const players=[...nameList(),...(gameState.extraPlayers||[])];gameState.votes[b.dataset.person]=(gameState.votes[b.dataset.person]||0)+1;gameState.answers=gameState.answers||{};gameState.answers[players[Object.keys(gameState.answers).length]]=b.dataset.person;renderGame();return;}
 if(b.dataset.rps){playRPS(b.dataset.rps);return;}
 if(b.dataset.rank!==undefined){const i=Number(b.dataset.rank);gameState.placed=gameState.placed||Array(5).fill(null);gameState.placed[i]=gameState.items[gameState.idx||0];gameState.idx=(gameState.idx||0)+1;if(gameState.idx>=5){completeRound(15,'Blind ranking completed');}renderGame();return;}
 if(b.dataset.bluff!==undefined){const pick=Number(b.dataset.bluff);gameState.pick=pick;gameState.correct=pick===gameState.bluff[5];gameState.revealed=true;if(gameState.correct){state.wins++;completeRound(15,'Bluff spotted');}renderGame();return;}
 if(b.dataset.bingo!==undefined){const i=Number(b.dataset.bingo);gameState.done=gameState.done||[];gameState.done=gameState.done.includes(i)?gameState.done.filter(v=>v!==i):[...gameState.done,i];renderGame();return;}
 if(b.dataset.memory!==undefined){memoryTap(Number(b.dataset.memory));return;}
 if(b.dataset.vibe){gameState.vibe=b.dataset.vibe;renderGame();return;}
 if(b.dataset.budget){gameState.budget=b.dataset.budget;renderGame();return;}
 if(b.dataset.place){gameState.place=b.dataset.place;renderGame();return;}
 if(b.dataset.flag){gameState.flagVotes=gameState.flagVotes||{};const person=nameList()[Object.keys(gameState.flagVotes).length];if(person)gameState.flagVotes[person]=b.dataset.flag;renderGame();return;}
 if(b.dataset.same){gameState.sameAnswers=gameState.sameAnswers||[];gameState.sameAnswers[gameState.step||0]=b.dataset.same;gameState.step=(gameState.step||0)+1;if(gameState.step>=2){gameState.step=2;if(gameState.sameAnswers[0]===gameState.sameAnswers[1]){state.wins++;completeRound(15,'Same brain match');}}renderGame();return;}
 if(b.dataset.avatar){state.profile.avatar=b.dataset.avatar;saveState();render();return;}
 const a=b.dataset.action;if(a)handleAction(a);
});
function playTTT(i){const s=gameState;if(s.board[i]||checkTTT(s.board)||s.board.every(Boolean))return;s.board[i]=s.turn;let winner=checkTTT(s.board);if(winner){if(winner==='X'){s.matchWins=(s.matchWins||0)+1;state.wins++;completeRound(15,'Tic Tac Toe win');}else s.oppWins=(s.oppWins||0)+1;}else if(s.mode==='computer'){s.turn='O';const move=botMove(s.board,s.aiLevel||'medium');if(move!==undefined&&move!==null)s.board[move]='O';if(checkTTT(s.board))s.oppWins=(s.oppWins||0)+1;s.turn='X';}else s.turn=s.turn==='X'?'O':'X';if(!winner&&!s.board.every(Boolean)&&s.mode==='friend'){}renderGame();}
function playRPS(choice){if((gameState.rpsScore||[0,0]).some(v=>v>=3))return;const bot=rand(['Rock','Paper','Scissors']);const win=choice===bot?'draw':(choice==='Rock'&&bot==='Scissors')||(choice==='Paper'&&bot==='Rock')||(choice==='Scissors'&&bot==='Paper')?'win':'lose';gameState.rpsChoice=choice;gameState.rpsBot=bot;gameState.rpsResult=win==='draw'?'Draw!':win==='win'?'You win!':'Computer wins!';gameState.rpsScore=gameState.rpsScore||[0,0];if(win==='win'){gameState.rpsScore[0]++;state.wins++;completeRound(5,'Rock Paper Scissors win');}else if(win==='lose')gameState.rpsScore[1]++;if(gameState.rpsScore[0]>=3)toast('You won the match!');if(gameState.rpsScore[1]>=3)toast('Computer won this match. Try again!');renderGame();}
function memoryTap(i){if(memoryMatched.includes(i)||memoryOpened.includes(i)||memoryOpened.length===2)return;memoryOpened.push(i);renderGame();if(memoryOpened.length===2){gameState.moves=(gameState.moves||0)+1;if(gameState.cards[memoryOpened[0]]===gameState.cards[memoryOpened[1]]){memoryMatched.push(...memoryOpened);memoryOpened=[];renderGame();}else setTimeout(()=>{memoryOpened=[];renderGame();},800);}}

function handleAction(a){switch(a){
case 'close-game':closeGame();break;
case 'next-td':gameState.prompt=null;gameState.round++;completeRound(5,'Truth or Dare round');renderGame();break;
case 'skip-td':gameState.prompt=null;gameState.skips++;gameState.round++;toast('Prompt skipped. No pressure.');renderGame();break;
case 'reset-ttt':gameState.board=Array(9).fill('');gameState.turn=gameState.mode==='computer'?'X':'X';renderGame();break;
case 'new-ttt':gameState.board=Array(9).fill('');gameState.turn='X';gameState.matchWins=0;gameState.oppWins=0;renderGame();break;
case 'ludo-roll':{const s=gameState.ludo;const die=1+Math.floor(Math.random()*6);s.dice=die;s.legal=legalLudo(s,die);if(s.legal.length){s.rolled=true;}else{if(die!==6)s.turn=(s.turn+1)%s.players.length;s.rolled=false;s.dice=null;}renderGame();if(!s.winner&&s.players[s.turn].bot)autoLudoBot();break;}
case 'ludo-reset':gameState.ludo=null;renderGame();break;
case 'next-choice':if(gameState.revealed){gameState.round++;gameState.choice=null;gameState.votes={};gameState.revealed=false;completeRound(10,'Choice game');}else{gameState.revealed=true;completeRound(5,'Group vote revealed');}renderGame();break;
case 'next-never':if(gameState.revealed){gameState.round++;gameState.prompt=null;gameState.answers={};gameState.revealed=false;completeRound(10,'Never Have I Ever round');}else gameState.revealed=true;renderGame();break;
case 'next-most':if(gameState.revealed){gameState.round++;gameState.prompt=null;gameState.votes={};gameState.answers={};gameState.revealed=false;completeRound(10,'Most Likely To round');}else gameState.revealed=true;renderGame();break;
case 'quiz-lock':gameState.real=document.getElementById('quiz-real')?.value.trim();if(!gameState.real){toast('Write your answer first.');return;}gameState.step=1;renderGame();break;
case 'quiz-reveal':gameState.guess=document.getElementById('quiz-guess')?.value.trim();if(!gameState.guess){toast('Add your guess first.');return;}gameState.match=norm(gameState.real)===norm(gameState.guess);gameState.step=2;if(gameState.match){gameState.score=(gameState.score||0)+1;state.wins++;completeRound(15,'Partner quiz match');}renderGame();break;
case 'quiz-next':gameState.round++;gameState.question=pickUnique(PARTNER_QUESTIONS,'partner');gameState.step=0;gameState.real='';gameState.guess='';gameState.match=false;renderGame();break;
case 'story-save':{const v=document.getElementById('story-note')?.value.trim();if(!v){toast('Write a memory first.');return;}gameState.memory=v;completeRound(10,'Our Story memory');renderGame();break;}
case 'story-next':gameState.question=pickUnique(STORY_QUESTIONS,'our-story');gameState.round++;gameState.memory='';renderGame();break;
case 'word-start':gameState.revealed=true;gameState.seconds=30;renderGame();startWordTimer();break;
case 'word-point':gameState.score=(gameState.score||0)+1;completeRound(10,'Word guessed');gameState.round++;gameState.word=pickUnique(WORDS,'guess-word');gameState.revealed=true;gameState.seconds=30;renderGame();startWordTimer();break;
case 'word-skip':gameState.round++;gameState.word=pickUnique(WORDS,'guess-word');gameState.seconds=30;renderGame();startWordTimer();break;
case 'word-next':if(wordInterval)clearInterval(wordInterval);wordInterval=null;gameState.round++;gameState.word=pickUnique(WORDS,'guess-word');gameState.revealed=false;gameState.seconds=30;renderGame();break;
case 'rps-reset':gameState.rpsScore=[0,0];gameState.rpsChoice=null;gameState.rpsBot=null;gameState.rpsOver=false;renderGame();break;
case 'rank-reset':gameState.items=shuffle(RANK_ITEMS).slice(0,5);gameState.placed=Array(5).fill(null);gameState.idx=0;renderGame();break;
case 'mission-reveal':gameState.revealed=!gameState.revealed;renderGame();break;
case 'mission-done':completeRound(20,'Secret mission completed');gameState.missionNo=(gameState.missionNo||1)+1;gameState.mission=pickUnique(MISSIONS,'missions');gameState.revealed=false;renderGame();break;
case 'mission-next':gameState.mission=pickUnique(MISSIONS,'missions');gameState.missionNo=(gameState.missionNo||1)+1;gameState.revealed=true;renderGame();break;
case 'emoji-check':{const v=norm(document.getElementById('emoji-answer')?.value);if(v&&v===norm(gameState.emoji[1])){gameState.correct=true;state.wins++;completeRound(15,'Emoji Decode solved');}else toast('Not quite — try again or reveal.');renderGame();break;}
case 'emoji-next':if(gameState.revealed){gameState.round++;gameState.emoji=pickUnique(EMOJI_QUIZ,'emoji');gameState.revealed=false;}else gameState.revealed=true;renderGame();break;
case 'bluff-next':if(gameState.revealed){gameState.round++;gameState.bluff=pickUnique(BLUFFS,'bluff');gameState.revealed=false;gameState.pick=undefined;gameState.correct=false;}else toast('Pick an answer first.');renderGame();break;
case 'bingo-reset':gameState.bingo=shuffle(BINGO_TASKS).slice(0,9);gameState.done=[];renderGame();break;
case 'bingo-clear':gameState.done=[];renderGame();break;
case 'memory-reset':gameState.cards=null;memoryOpened=[];memoryMatched=[];gameState.moves=0;renderGame();break;
case 'memory-finish':completeRound(20,'Memory match completed');closeGame();break;
case 'story-line-add':{const v=document.getElementById('story-line')?.value.trim();if(!v){toast('Add a line first.');return;}gameState.lines=gameState.lines||[];gameState.lines.push(v);renderGame();break;}
case 'story-finish':gameState.finished=true;completeRound(15,'Story built together');renderGame();break;
case 'story-new':gameState.lines=[];gameState.finished=false;gameState.seed='It was a perfectly ordinary evening until…';renderGame();break;
case 'story-copy':copyText((gameState.lines||[]).join('\n'));break;
case 'date-generate':{const list=DATE_IDEAS[gameState.vibe||'cosy'];let idea=rand(list);if(gameState.place==='indoor')idea='At home: '+idea;if(gameState.place==='outdoor')idea='Go out: '+idea;const b=gameState.budget||'low';idea+=b==='low'?' · Budget-friendly':b==='mid'?' · Mid-range idea':' · Make it a special treat';gameState.idea=idea;completeRound(5,'Date night plan generated');renderGame();break;}
case 'share-result':shareText(`Our YaarJam date idea: ${gameState.idea}`);break;
case 'flag-next':if(Object.keys(gameState.flagVotes||{}).length>=2){gameState.round++;gameState.flag=pickUnique(RED_FLAGS,'redflag');gameState.flagVotes={};completeRound(5,'Red flag round');}renderGame();break;
case 'same-next':gameState.round++;gameState.same=pickUnique(SAME_BRAIN,'samebrain');gameState.sameAnswers=[];gameState.step=0;renderGame();break;
case 'twenty-host-reveal':gameState.hostRevealed=true;renderGame();break;
case 'twenty-hide':gameState.hostRevealed=false;gameState.started=true;renderGame();break;
case 'twenty-answer-yes':case 'twenty-answer-no':gameState.lastAnswer=a==='twenty-answer-yes'?'Yes':'No';gameState.qCount=(gameState.qCount||0)+1;renderGame();break;
case 'twenty-guess':{const guess=document.getElementById('twenty-guess')?.value.trim();if(!guess){toast('Type your guess first.');return;}if(norm(guess)===norm(gameState.object[0])){gameState.revealed=true;state.wins++;completeRound(20,'20 Questions solved');}else{toast('Not the mystery item yet. Keep asking!');}renderGame();break;}
case 'twenty-hint':gameState.hints=gameState.hints||[];if(gameState.hints.length<3)gameState.hints.push(gameState.object[3+gameState.hints.length]);renderGame();break;
case 'twenty-reveal':gameState.revealed=true;renderGame();break;
case 'twenty-count':gameState.qCount=(gameState.qCount||0)+1;renderGame();break;
case 'twenty-new':gameState.object=pickUnique(OBJECTS,'twenty');gameState.qCount=0;gameState.hints=[];gameState.revealed=false;gameState.started=false;gameState.hostRevealed=false;gameState.lastAnswer='';gameState.round++;renderGame();break;
case 'reaction-start':gameState.phase='waiting';gameState.reactor=nameList()[(gameState.reactionTimes||[]).length]||nameList()[0];renderGame();if(reactionTimer)clearTimeout(reactionTimer);reactionTimer=setTimeout(()=>{reactionReady=true;reactionStart=performance.now();gameState.phase='ready';renderGame();},1800+Math.random()*2600);break;
case 'reaction-next-player':gameState.phase='idle';gameState.reactor=nameList()[1];renderGame();break;
case 'reaction-reset':gameState.phase='idle';gameState.reactionTimes=[];gameState.reactor=nameList()[0];gameState.time=null;renderGame();break;
case 'reaction-tap':if(gameState.phase==='waiting'){clearTimeout(reactionTimer);reactionTimer=null;gameState.phase='false';toast('Too early! Wait for green.');renderGame();}else if(gameState.phase==='ready'&&reactionReady){gameState.time=Math.round(performance.now()-reactionStart);gameState.phase='done';reactionReady=false;gameState.reactionTimes=gameState.reactionTimes||[];gameState.reactionTimes.push(gameState.time);if(gameState.reactionTimes.length>=2){const times=gameState.reactionTimes;if(times[0]!==times[1]){state.wins++;completeRound(15,'Reaction battle completed');}else completeRound(5,'Reaction battle tie');}renderGame();}break;
case 'clear-search':searchText='';render();break;
case 'save-names':{state.profile.name=document.getElementById('profile-name-inline').value.trim()||'Player One';state.profile.partner=document.getElementById('partner-name-inline').value.trim()||'Player Two';state.profile.groupNames=document.getElementById('group-names-inline').value.split(',').map(v=>v.trim()).filter(Boolean).slice(0,10).join(', ')||`${state.profile.name}, ${state.profile.partner}`;const group=state.profile.groupNames.split(',').map(v=>v.trim());if(group.length>10){toast('Maximum 10 players are supported.');return;}saveState();toast('Player names saved.');render();break;}
case 'save-profile':{state.profile.name=document.getElementById('profile-name').value.trim()||'Player One';state.profile.partner=document.getElementById('profile-partner').value.trim()||'Player Two';state.profile.groupNames=(document.getElementById('profile-group-names')?.value||`${state.profile.name}, ${state.profile.partner}`).split(',').map(v=>v.trim()).filter(Boolean).slice(0,10).join(', ');saveState();toast('Profile saved.');render();break;}
case 'add-deck':{const type=document.getElementById('deck-type').value;const text=document.getElementById('deck-prompt').value.trim();if(!text){toast('Write a prompt first.');return;}if(type==='would-you-rather'&&!text.includes('|')){toast('Use option A | option B format.');return;}state.customDeck.push({id:Date.now(),type,text});saveState();toast('Added to your custom deck.');render();break;}
case 'view-deck':showDeckModal();break;
case 'export':exportBackup();break;
case 'import':document.getElementById('backup-file')?.click();break;
case 'reset-data':confirmModal('Reset all local data?','This erases your profile, XP, game history and custom prompts on this device.',()=>{localStorage.removeItem(STORE_KEY);state=structuredClone(DEFAULTS);render();toast('Local data reset.');});break;
case 'playlist':{playlistQueue=['emoji-decode','blind-ranking','reaction-battle'];openGame('truth-dare-friends');toast('Game Night playlist started. Close a game to continue.');break;}
}}
function startWordTimer(){if(wordInterval)clearInterval(wordInterval);let sec=30;wordInterval=setInterval(()=>{if(!currentGame||currentGame!=='guess-word'){clearInterval(wordInterval);wordInterval=null;return;}sec--;gameState.seconds=sec;const el=document.getElementById('word-timer');if(el)el.textContent=sec+'s';if(sec<=0){clearInterval(wordInterval);wordInterval=null;toast('Time is up!');}},1000);}
function copyText(text){if(navigator.clipboard?.writeText){navigator.clipboard.writeText(text).then(()=>toast('Copied to clipboard.')).catch(()=>toast('Could not copy.'));}else toast('Copy is not supported in this browser.');}
function shareText(text){if(navigator.share){navigator.share({title:'YaarJam',text}).then(()=>{}).catch(()=>{});}else copyText(text);}
function showDeckModal(){const backdrop=document.createElement('div');backdrop.className='modal-backdrop';backdrop.innerHTML=`<div class="modal-card"><div style="display:flex;justify-content:space-between;align-items:center"><h3>Your custom deck (${state.customDeck.length})</h3><button class="close-game" data-modal-close>✕</button></div>${state.customDeck.length?state.customDeck.map(d=>`<div class="list-row"><div><b>${esc(d.type)}</b><small>${esc(d.text)}</small></div><button class="danger-btn" data-delete-deck="${d.id}">Remove</button></div>`).join(''):'<p class="muted">No prompts yet.</p>'}</div>`;document.body.append(backdrop);backdrop.addEventListener('click',e=>{if(e.target===backdrop||e.target.closest('[data-modal-close]'))backdrop.remove();if(e.target.dataset.deleteDeck){state.customDeck=state.customDeck.filter(d=>d.id!==Number(e.target.dataset.deleteDeck));saveState();backdrop.remove();showDeckModal();}});}
function confirmModal(title,desc,yes){const backdrop=document.createElement('div');backdrop.className='modal-backdrop';backdrop.innerHTML=`<div class="modal-card"><h3>${title}</h3><p class="muted">${desc}</p><div class="game-actions"><button class="danger-btn" data-yes>Yes, reset</button><button class="secondary-btn" data-no>Cancel</button></div></div>`;document.body.append(backdrop);backdrop.addEventListener('click',e=>{if(e.target.dataset.no||e.target===backdrop)backdrop.remove();if(e.target.dataset.yes){backdrop.remove();yes();}});}
function exportBackup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='yaarjam-backup.json';a.click();URL.revokeObjectURL(url);toast('Backup exported.');}
function importBackup(file){const reader=new FileReader();reader.onload=()=>{try{const imported=JSON.parse(reader.result);if(!imported||typeof imported!=='object'||!imported.profile)throw new Error('Invalid backup');state={...structuredClone(DEFAULTS),...imported,profile:{...DEFAULTS.profile,...imported.profile},stats:{...DEFAULTS.stats,...(imported.stats||{})}};saveState();render();toast('Backup imported.');}catch{toast('That backup file is not valid.');}};reader.readAsText(file);}
function onChange(e){if(e.target.id==='game-search'){searchText=e.target.value;const pos=e.target.selectionStart;render();const input=document.getElementById('game-search');input?.focus();input?.setSelectionRange(pos,pos);}if(e.target.id==='sound-setting'||e.target.id==='haptic-setting'){state.profile[e.target.id==='sound-setting'?'sound':'haptics']=e.target.checked;saveState();}if(e.target.id==='backup-file'&&e.target.files?.[0])importBackup(e.target.files[0]);}
document.addEventListener('input',e=>{if(e.target.id==='game-search')onChange(e);});document.addEventListener('change',onChange);

function boot(){if(state.lastVisit!==todayKey){const yesterday=new Date(Date.now()-86400000).toISOString().slice(0,10);state.streak=state.lastVisit===yesterday?(state.streak||0)+1:1;state.lastVisit=todayKey;saveState();}render();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});}
boot();
